53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        List<String> missingFields = new ArrayList<>();
105	        if (isBlank(ownerFieldsDto.getFirstName())) {
106	            missingFields.add("firstName");
107	        }
108	        if (isBlank(ownerFieldsDto.getLastName())) {
109	            missingFields.add("lastName");
110	        }
111	        if (isBlank(ownerFieldsDto.getAddress())) {
112	            missingFields.add("address");
113	        }
114	        if (isBlank(ownerFieldsDto.getCity())) {
115	            missingFields.add("city");
116	        }
117	        if (isBlank(ownerFieldsDto.getTelephone())) {
118	            missingFields.add("telephone");
119	        }
120	        if (!missingFields.isEmpty()) {
121	            throw new MissingOwnerFieldsException(missingFields);
122	        }
123	        HttpHeaders headers = new HttpHeaders();
124	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
125	        this.clinicService.saveOwner(owner);
126	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
127	        headers.setLocation(UriComponentsBuilder.newInstance()
128	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
129	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
135	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
136	        if (currentOwner == null) {
137	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
138	        }
139	        currentOwner.setAddress(ownerFieldsDto.getAddress());
140	        currentOwner.setCity(ownerFieldsDto.getCity());
141	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
142	        currentOwner.setLastName(ownerFieldsDto.getLastName());
143	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
144	        this.clinicService.saveOwner(currentOwner);
145	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Transactional
150	    @Override
151	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
152	        Owner owner = this.clinicService.findOwnerById(ownerId);
153	        if (owner == null) {
154	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
155	        }
156	        this.clinicService.deleteOwner(owner);
157	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Override
162	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
163	        Owner owner = this.clinicService.findOwnerById(ownerId);
164	        if (owner == null) {
165	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
166	        }
167	        HttpHeaders headers = new HttpHeaders();
168	        Pet pet = petMapper.toPet(petFieldsDto);
169	        owner.setId(ownerId);
170	        pet.setOwner(owner);
171	        pet.getType().setName(null);
172	        this.clinicService.savePet(pet);
173	        PetDto petDto = petMapper.toPetDto(pet);
174	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
175	            .buildAndExpand(pet.getId()).toUri());
176	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
182	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
183	        if (currentOwner != null) {
184	            Pet currentPet = this.clinicService.findPetById(petId);
185	            if (currentPet != null) {
186	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
187	                currentPet.setName(petFieldsDto.getName());
188	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
189	                this.clinicService.savePet(currentPet);
190	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
191	            }
192	        }
193	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	    }
195	
196	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
197	    @Override
198	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
199	        HttpHeaders headers = new HttpHeaders();
200	        Visit visit = visitMapper.toVisit(visitFieldsDto);
201	        Pet pet = new Pet();
202	        pet.setId(petId);
203	        visit.setPet(pet);
204	        this.clinicService.saveVisit(visit);
205	        VisitDto visitDto = visitMapper.toVisitDto(visit);
206	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
207	            .buildAndExpand(visit.getId()).toUri());
208	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
209	    }
210	
211	
212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Override
214	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
215	        Owner owner = this.clinicService.findOwnerById(ownerId);
216	        if (owner != null) {
217	            Pet pet = owner.getPet(petId);
218	            if (pet != null) {
219	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
220	            }
221	        }
222	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
223	    }
224	
225	    private static boolean isBlank(String value) {
226	        return value == null || value.isBlank();
227	    }
228	}
